<template><el-container class="shop"><el-header><el-button @click="router.push('/health-home')">返回健康首页</el-button><h3>健康商城</h3><el-tag type="warning">本地教学模式</el-tag></el-header><el-main><el-alert title="演示结算不会发生真实付款；沙箱结算需先完成本地配置" type="info" :closable="false"/><h2>健康服务优惠券</h2><el-row :gutter="20"><el-col v-for="g in goods" :key="g.id" :xs="24" :sm="12" :lg="8"><el-card><section class="coupon">健康服务 · 优惠券</section><h3>{{g.title}}</h3><p class="price">¥{{g.price}}</p><p>剩余 {{g.stock}} 份</p><p>活动 {{g.start_time}} 至 {{g.end_time}}</p><el-button type="primary" @click="router.push('/health-shop/'+g.id)">查看商品详情</el-button></el-card></el-col></el-row><h2>我的订单</h2><el-table :data="orders"><el-table-column prop="title" label="商品"/><el-table-column prop="amount" label="金额"/><el-table-column prop="status" label="状态"/><el-table-column prop="expires_at" label="支付截止时间"/><el-table-column label="操作" width="440"><template #default="s"><el-space v-if="s.row.status==='RESERVED'"><el-button @click="cancel(s.row)">退单</el-button><el-button v-if="payment.demoEnabled" type="primary" @click="pay(s.row)">本地演示结算</el-button><el-button :disabled="!payment.sandboxConfigured" @click="sandbox(s.row)">支付宝沙箱结算</el-button></el-space><el-tag v-else>{{s.row.status==='PAID'?'已结算（付款渠道见核验页）':s.row.status}}</el-tag></template></el-table-column></el-table></el-main></el-container></template>
<script setup>
import {ref,onMounted} from 'vue';import {useRouter} from 'vue-router';import {ElMessage,ElMessageBox} from 'element-plus';import {call} from '@/api/health'
const router=useRouter(),goods=ref([]),orders=ref([]),busy=ref(null),payment=ref({})
async function load(){payment.value=(await call('shop/payment-configuration')).data;goods.value=(await call('shop/goods')).data;orders.value=(await call('shop/orders')).data}
async function reserve(g){busy.value=g.id;try{await call('shop/reserve/'+g.id,'post');ElMessage.success('抢购成功，请在30分钟内结算');await load()}finally{busy.value=null}}
async function cancel(o){await ElMessageBox.confirm('确认退单？同一商品退单三次后不可再次抢购。','退单确认');await call('shop/orders/'+o.id+'/cancel','post');await load()}
async function pay(o){await ElMessageBox.confirm('这仅记录本地教学支付状态，不发生任何真实付款。','本地演示结算');await call('shop/orders/'+o.id+'/demo-pay','post');ElMessage.success('教学结算完成');await load()}
async function sandbox(o){const result=await call('shop/orders/'+o.id+'/checkout','post');window.location.assign(result.data.checkoutUrl)}
onMounted(load)
</script><style scoped>.shop{background:#f1f7f6;min-height:100vh}.el-header{display:flex;align-items:center;gap:20px;background:white}.el-main{padding:32px 5vw}.el-card{margin-bottom:20px}.coupon{padding:40px;background:#d5efe8;color:#126e5b;font-size:24px;border-radius:8px}.price{font-size:30px;color:#137c70}</style>
